// The city's texts (city.js) in Slovenian, as the sentences take them: server in the genitive ("Strežnik mesta Brno
// se ne odziva"), dataName in the nominative ("… se trenutno ne odziva"), dataShort in the genitive ("po podatkih
// mesta Brno in OSM"), techMap in the genitive after "Nalaganje …" (so own() takes the map in both cases).
const own = (name, of, map, mapOf, data, parking, credit) => ({
  server: of, dataName: map, dataShort: `${data} in OSM`, techMap: mapOf,
  parkingSource: parking, rulesHead: `Širine po praškem priročniku IPR (C.2), za mesto ${name} okvirno:`, credit,
});
